  constructor(tokens: Token[]) {
    this.tokens = tokens;
  }

  parse(): { program: Program; errors: ParseError[] } {
    const stmts: Stmt[] = [];
    while (!this.isAtEnd()) {
      try {
        stmts.push(this.parseStmt());
      } catch (e) {
        // 에러 복구: 다음 문 시작까지 건너뜀
        this.synchronize();
      }

