// ============================================================
// Environment (스코프 체인)
// ============================================================

export class Env {
  private vars: Map<string, RuntimeValue> = new Map();
  constructor(public parent: Env | null = null) {}

  get(name: string): RuntimeValue {
    if (this.vars.has(name)) return this.vars.get(name)!;
    if (this.parent) return this.parent.get(name);
    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
  }

  set(name: string, val: RuntimeValue): void {
    this.vars.set(name, val);
  }

  assign(name: string, val: RuntimeValue): void {
    if (this.vars.has(name)) { this.vars.set(name, val); return; }
    if (this.parent) { this.parent.assign(name, val); return; }
    throw new RuntimeError(`정의되지 않은 변수: ${name}`);
  }
}

