// FreeLang v8 ML — Collections 표준 라이브러리 (Phase 9)

// ============================================================
// HashMap<K, V>
// ============================================================

export class FL8HashMap<K = string, V = unknown> {
  private _map = new Map<K, V>();

  set(key: K, value: V): this { this._map.set(key, value); return this; }
  get(key: K): V | undefined { return this._map.get(key); }
  getOr(key: K, def: V): V { return this._map.has(key) ? this._map.get(key)! : def; }
  has(key: K): boolean { return this._map.has(key); }
  delete(key: K): boolean { return this._map.delete(key); }
  clear(): void { this._map.clear(); }
  size(): number { return this._map.size; }

  keys(): K[] { return [...this._map.keys()]; }
  values(): V[] { return [...this._map.values()]; }
  entries(): [K, V][] { return [...this._map.entries()]; }

  forEach(fn: (v: V, k: K) => void): void { this._map.forEach(fn); }

  map<R>(fn: (v: V, k: K) => R): FL8HashMap<K, R> {
    const out = new FL8HashMap<K, R>();
    this._map.forEach((v, k) => out.set(k, fn(v, k)));
    return out;
  }

  filter(fn: (v: V, k: K) => boolean): FL8HashMap<K, V> {
    const out = new FL8HashMap<K, V>();
    this._map.forEach((v, k) => { if (fn(v, k)) out.set(k, v); });
    return out;
  }

  toObject(): Record<string, V> {
    const obj: Record<string, V> = {};
    this._map.forEach((v, k) => { obj[String(k)] = v; });
    return obj;
  }

  static fromObject<V>(obj: Record<string, V>): FL8HashMap<string, V> {
    const m = new FL8HashMap<string, V>();
    for (const [k, v] of Object.entries(obj)) m.set(k, v);
    return m;
  }
}

// ============================================================
// Queue<T> — FIFO
// ============================================================

export class FL8Queue<T = unknown> {
  private _items: T[] = [];
  private _head = 0;  // 링 버퍼 최적화

  enqueue(item: T): void { this._items.push(item); }

  dequeue(): T | undefined {
    if (this._head >= this._items.length) return undefined;
    const item = this._items[this._head++];
    // 절반 이상 빈 공간이면 배열 압축
    if (this._head > 64 && this._head > this._items.length >> 1) {
      this._items = this._items.slice(this._head);
      this._head = 0;
    }
    return item;
  }

  peek(): T | undefined {
    return this._head < this._items.length ? this._items[this._head] : undefined;
  }

  isEmpty(): boolean { return this._head >= this._items.length; }
  size(): number { return this._items.length - this._head; }
  clear(): void { this._items = []; this._head = 0; }
  toArray(): T[] { return this._items.slice(this._head); }
}

// ============================================================
// Stack<T> — LIFO
// ============================================================

export class FL8Stack<T = unknown> {
  private _items: T[] = [];

  push(item: T): void { this._items.push(item); }
  pop(): T | undefined { return this._items.pop(); }
  peek(): T | undefined { return this._items[this._items.length - 1]; }
  isEmpty(): boolean { return this._items.length === 0; }
  size(): number { return this._items.length; }
  clear(): void { this._items = []; }
  toArray(): T[] { return [...this._items].reverse(); }  // top → bottom
}

// ============================================================
// PriorityQueue<T> — Min-Heap
// ============================================================

export class FL8PriorityQueue<T = unknown> {
  private _heap: [number, T][] = [];  // [priority, value]

  // 낮은 priority = 높은 우선순위 (min-heap)
  enqueue(item: T, priority: number): void {
    this._heap.push([priority, item]);
    this._bubbleUp(this._heap.length - 1);
  }

  dequeue(): T | undefined {
    if (this._heap.length === 0) return undefined;
    const top = this._heap[0][1];
    const last = this._heap.pop()!;
    if (this._heap.length > 0) {
      this._heap[0] = last;
      this._sinkDown(0);
    }
    return top;
  }

  peek(): T | undefined { return this._heap.length > 0 ? this._heap[0][1] : undefined; }

