// FreeLang v8 ML - 옵티마이저 (SGD, Adam, AdamW, RMSProp + LR 스케줄러)
import { Value } from './autodiff';
import { LRScheduler } from './tensor_ops';

export interface Optimizer {
  step(params: Value[]): void;
  zeroGrad(params: Value[]): void;
}

export class SGD implements Optimizer {
  constructor(public lr = 0.01, public momentum = 0.0) {}
  private velocity = new Map<Value, number>();

  step(params: Value[]): void {
    for (const p of params) {
      const v = (this.velocity.get(p) ?? 0) * this.momentum - this.lr * p.grad;
      this.velocity.set(p, v);
      p.data += v;
    }
  }

  zeroGrad(params: Value[]): void {
    for (const p of params) p.grad = 0;
  }
}

export class Adam implements Optimizer {
  private t = 0;
  private m = new Map<Value, number>();
  private v = new Map<Value, number>();

  constructor(
    public lr = 0.001,
    public beta1 = 0.9,
    public beta2 = 0.999,
    public eps = 1e-8
  ) {}

  step(params: Value[]): void {
    this.t++;
    for (const p of params) {
      const g = p.grad;
      const m = (this.m.get(p) ?? 0) * this.beta1 + (1 - this.beta1) * g;
      const v = (this.v.get(p) ?? 0) * this.beta2 + (1 - this.beta2) * g * g;
      this.m.set(p, m);
      this.v.set(p, v);
      const mHat = m / (1 - Math.pow(this.beta1, this.t));
      const vHat = v / (1 - Math.pow(this.beta2, this.t));
      p.data -= this.lr * mHat / (Math.sqrt(vHat) + this.eps);
    }
  }

  zeroGrad(params: Value[]): void {
    for (const p of params) p.grad = 0;
  }
}

