export type Shape = number[];

// ============================================================
// 1. Tiled Matmul (캐시 친화적)
//    naïve: O(N*M*K) 캐시 미스 多
//    tiled: 블록 단위 처리로 L1 캐시 적중률 향상
// ============================================================

const TILE = 32;

export function matmulTiled(
  A: Float32Array, B: Float32Array,
  N: number, M: number, K: number,
  C?: Float32Array
): Float32Array {
  const out = C ?? new Float32Array(N * K);

  for (let i0 = 0; i0 < N; i0 += TILE) {
    for (let k0 = 0; k0 < K; k0 += TILE) {
      for (let j0 = 0; j0 < M; j0 += TILE) {
        const iEnd = Math.min(i0 + TILE, N);
        const kEnd = Math.min(k0 + TILE, K);
        const jEnd = Math.min(j0 + TILE, M);
        for (let i = i0; i < iEnd; i++) {
          const rowA = i * M;
          const rowC = i * K;
          for (let k = k0; k < kEnd; k++) {
            const rowB = j0 * K;  // B는 [M,K] → row j*K
            let s = 0;
            for (let j = j0; j < jEnd; j++) {
              s += A[rowA + j] * B[j * K + k];
            }
            out[rowC + k] += s;
          }
        }
      }
    }
  }
  return out;
}

