// FL8 소스 → 타입 체크 결과
function check(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors: parseErrors } = new Parser(tokens).parse();
  if (parseErrors.length > 0) throw new Error(`파서: ${parseErrors[0].message}`);
  return typeCheck(program);
}

// FL8 소스 → 오류 없음 검증
function expectOk(src: string): ReturnType<typeof typeCheck> {
  const result = check(src);
  if (result.errors.length > 0) {
    throw new Error(`예상치 못한 타입 오류:\n  ${result.errors.map(e => e.message).join('\n  ')}`);
  }
  return result;
}

// FL8 소스 → 특정 오류 포함 검증
function expectError(src: string, kind: string): ReturnType<typeof typeCheck> {
  const result = check(src);
  const found = result.errors.some(e => e.kind === kind);
  if (!found) {
    const got = result.errors.map(e => e.kind).join(', ') || '없음';
    throw new Error(`'${kind}' 오류 기대, 실제: [${got}]`);
  }
  return result;
}

function run(src: string) {
  const { tokens } = new Lexer(src).tokenize();
  const { program, errors } = new Parser(tokens).parse();
  if (errors.length > 0) throw new Error(`파서: ${errors[0].message}`);
  new Interpreter().run(program);
}

// FreeLang v8 ML — 타입 체커 (Phase 8)
