// FreeLang v8 ML — 벤치마크 프레임워크 (Phase 14)

import * as fs from 'fs';

// ============================================================
// 타입 정의
// ============================================================

export interface BenchResult {
  name: string;
  category: string;
  runs: number;
  avgMs: number;
  minMs: number;
  maxMs: number;
  opsPerSec: number;
  throughput?: string; // 예: "1.2 MB/s"
}

export interface BenchSuite {
  name: string;
  results: BenchResult[];
  totalMs: number;
  timestamp: string;
}

// ============================================================
// bench() — 단일 벤치마크 실행
// ============================================================

export function bench(
  name: string,
  category: string,
  fn: () => void,
  runs = 100
): BenchResult {
  const times: number[] = [];

  // 워밍업 3회 (JIT 최적화 반영)
  for (let i = 0; i < 3; i++) {
    try { fn(); } catch (_) {}
  }

  for (let i = 0; i < runs; i++) {
    const t0 = performance.now();
    fn();
    const t1 = performance.now();
    times.push(t1 - t0);
  }

  const total = times.reduce((a, b) => a + b, 0);
  const avgMs = total / runs;
  const minMs = Math.min(...times);
  const maxMs = Math.max(...times);
  const opsPerSec = avgMs > 0 ? Math.round(1000 / avgMs) : 999999;

  return { name, category, runs, avgMs, minMs, maxMs, opsPerSec };
}

// ============================================================
// BenchmarkRunner — 복수 벤치마크 수집 및 실행
// ============================================================

interface BenchEntry {
  name: string;
  category: string;
  fn: () => void;
  runs: number;
}

export class BenchmarkRunner {
  private entries: BenchEntry[] = [];
  private suiteName: string;

  constructor(name = 'FreeLang v8 ML Benchmark Suite') {
    this.suiteName = name;
  }

  add(name: string, category: string, fn: () => void, runs = 100): this {
    this.entries.push({ name, category, fn, runs });
    return this;
  }

  run(): BenchSuite {
    const t0 = performance.now();
    const results: BenchResult[] = [];

    for (const e of this.entries) {
      const r = bench(e.name, e.category, e.fn, e.runs);
      results.push(r);
    }

    const totalMs = performance.now() - t0;

    return {
      name: this.suiteName,
      results,
      totalMs,
      timestamp: new Date().toISOString(),
    };
  }

  report(suite: BenchSuite): string {
    const lines: string[] = [];

    lines.push(`╔${'═'.repeat(78)}╗`);
    lines.push(`║  ${suite.name.padEnd(76)}║`);
    lines.push(`║  ${suite.timestamp.padEnd(76)}║`);
    lines.push(`╚${'═'.repeat(78)}╝`);
    lines.push('');

    // 카테고리별 그룹핑
    const byCategory = new Map<string, BenchResult[]>();
    for (const r of suite.results) {
      const arr = byCategory.get(r.category) ?? [];
      arr.push(r);
      byCategory.set(r.category, arr);
    }

    const COL_NAME = 36;
    const COL_RUNS = 6;
    const COL_AVG  = 10;
    const COL_MIN  = 10;
    const COL_MAX  = 10;
    const COL_OPS  = 12;

    const header =
      'Name'.padEnd(COL_NAME) +
      'Runs'.padStart(COL_RUNS) +
      'Avg(ms)'.padStart(COL_AVG) +
      'Min(ms)'.padStart(COL_MIN) +
      'Max(ms)'.padStart(COL_MAX) +
      'ops/sec'.padStart(COL_OPS);
    const divider = '─'.repeat(header.length);

    for (const [cat, results] of byCategory.entries()) {
      lines.push(`▶ ${cat}`);
      lines.push(divider);
      lines.push(header);
      lines.push(divider);

      for (const r of results) {
        const throughput = r.throughput ? ` [${r.throughput}]` : '';
        const nameField = (r.name + throughput).substring(0, COL_NAME).padEnd(COL_NAME);
        const row =
          nameField +
          String(r.runs).padStart(COL_RUNS) +
          r.avgMs.toFixed(3).padStart(COL_AVG) +
          r.minMs.toFixed(3).padStart(COL_MIN) +
          r.maxMs.toFixed(3).padStart(COL_MAX) +
          String(r.opsPerSec).padStart(COL_OPS);
        lines.push(row);
      }

      lines.push(divider);
      lines.push('');
    }

    lines.push(`총 실행 시간: ${suite.totalMs.toFixed(1)}ms | 벤치마크 수: ${suite.results.length}개`);
    return lines.join('\n');
  }

  saveJson(suite: BenchSuite, filePath: string): void {
    const dir = filePath.substring(0, filePath.lastIndexOf('/'));
    if (dir && !fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(filePath, JSON.stringify(suite, null, 2), 'utf-8');
  }
}

