// FreeLang v8 ML — 벤치마크 스위트 (Phase 14)
// Phase 1~13 전반의 성능 측정

import { BenchmarkRunner } from './benchmark';
import { Lexer } from '../lexer/lexer';
import { Parser } from '../parser/parser';
import { Interpreter } from '../runtime/interpreter';
import { matmulTiled, BufferPool } from '../ml/tensor_ops';
import { Adam } from '../ml/optimizer';
import { Value } from '../ml/autodiff';
import {
  FL8HashMap,
  FL8Queue,
  FL8PriorityQueue,
} from '../stdlib/collections';
import { Lexer as FL8Lexer } from '../lexer/lexer';
import { typeCheck } from '../types/type_checker';

// ============================================================
// 헬퍼: FL8 소스 → 토큰 배열
// ============================================================

function tokenize(src: string) {
  return new Lexer(src).tokenize().tokens;
}

function parseSource(src: string) {
  const tokens = tokenize(src);
  return new Parser(tokens).parse();
}

// ============================================================
// 소스 픽스처
// ============================================================

const SHORT_SRC = `var x: i32 = 42; var y: i32 = x + 1;`;

// 1000줄 소스: 100번 반복 10라인 블록
const LONG_SRC = Array.from({ length: 100 }, (_, i) => `
fn add${i}(a: i32, b: i32): i32 { return a + b; }
var r${i}: i32 = add${i}(${i}, ${i + 1});
`).join('\n');

const FIB_SRC = `
fn fib(n: i32): i32 {
  if n <= 1 { return n; }
  return fib(n - 1) + fib(n - 2);
}
var result: i32 = fib(20);
`;

const ARRAY_SRC = `
var arr: i32[] = [];
for i in 0..1000 { arr = arr + [i]; }
var sum: i32 = 0;
for x in arr { sum = sum + x; }
`;

const LOOP_SRC = `
var sum: i32 = 0;
for i in 0..10000 { sum = sum + i; }
`;

const NESTED_FN_SRC = `
fn f0(x: i32): i32 { return x + 1; }
fn f1(x: i32): i32 { return f0(x + 1); }
fn f2(x: i32): i32 { return f1(x + 1); }
fn f3(x: i32): i32 { return f2(x + 1); }
fn f4(x: i32): i32 { return f3(x + 1); }
fn f5(x: i32): i32 { return f4(x + 1); }
fn f6(x: i32): i32 { return f5(x + 1); }
fn f7(x: i32): i32 { return f6(x + 1); }
fn f8(x: i32): i32 { return f7(x + 1); }
fn f9(x: i32): i32 { return f8(x + 1); }
var result: i32 = f9(0);
`;

const TYPE_CHECK_SRC = `
var a: i32 = 10;
var b: f64 = 3.14;
fn add(x: i32, y: i32): i32 { return x + y; }
var c: i32 = add(a, 5);
`;

const ML_TYPE_SRC = `
var lr: f64 = 0.001;
var epochs: i32 = 100;
var loss: f64 = 0.5;
`;

// ============================================================
// 스위트 빌더: Lexer/Parser
// ============================================================

export function addLexerParserBenches(runner: BenchmarkRunner): void {
  runner.add(
    'lex_short (100자)',
    'Lexer/Parser',
    () => { new Lexer(SHORT_SRC).tokenize(); },
    200
  );

  runner.add(
    'lex_long (1000줄)',
    'Lexer/Parser',
    () => { new Lexer(LONG_SRC).tokenize(); },
    50
  );

  runner.add(
    'parse_long (lex+parse 50회)',
    'Lexer/Parser',
    () => {
      const tokens = tokenize(LONG_SRC);
      new Parser(tokens).parse();
    },
    50
  );

  // 같은 소스 반복 파싱 (캐시 효과 측정)
  const cachedTokens = tokenize(SHORT_SRC);
  runner.add(
    'parse_repeat_same (100회)',
    'Lexer/Parser',
    () => { new Parser([...cachedTokens]).parse(); },
    100
  );
}

// ============================================================
// 스위트 빌더: Interpreter
// ============================================================

export function addInterpreterBenches(runner: BenchmarkRunner): void {
  runner.add(
    'fib(20) 반복',
    'Interpreter',
    () => {
      const interp = new Interpreter();
      const { program } = parseSource(FIB_SRC);
      interp.run(program);
    },
    20
  );

  runner.add(
    'loop 10000회',
    'Interpreter',
    () => {
      const interp = new Interpreter();
      const { program } = parseSource(LOOP_SRC);
      interp.run(program);
    },
    20
  );

  runner.add(
    'fn 중첩 10레벨',
    'Interpreter',
    () => {
      const interp = new Interpreter();
      const { program } = parseSource(NESTED_FN_SRC);
      interp.run(program);
    },
    30
  );
}

// ============================================================
// 스위트 빌더: ML/Tensor
// ============================================================

export function addMLBenches(runner: BenchmarkRunner): void {
  // matmul 32x32
  const A32 = new Float32Array(32 * 32).fill(0).map(() => Math.random());
  const B32 = new Float32Array(32 * 32).fill(0).map(() => Math.random());

  runner.add(
    'matmul 32x32 (Tiled)',
    'ML/Tensor',
    () => { matmulTiled(A32, B32, 32, 32, 32); },
    200
  );

  // matmul 64x64
  const A64 = new Float32Array(64 * 64).fill(0).map(() => Math.random());
  const B64 = new Float32Array(64 * 64).fill(0).map(() => Math.random());

  runner.add(
    'matmul 64x64 (Tiled)',
    'ML/Tensor',
    () => { matmulTiled(A64, B64, 64, 64, 64); },
    100
  );

  // Adam step 1000회 (10개 파라미터)
  const adamOpt = new Adam(0.001);
  const params = Array.from({ length: 10 }, () => {
    const v = new Value(Math.random());
    v.grad = Math.random() * 0.1;
    return v;
  });

  runner.add(
    'Adam step x1000 (10 params)',
    'ML/Tensor',
    () => {
      for (let i = 0; i < 1000; i++) {
        // 그래디언트 시뮬레이션
        for (const p of params) p.grad = Math.random() * 0.01;
        adamOpt.step(params);
        adamOpt.zeroGrad(params);
      }
    },
    20
  );

  // BufferPool acquire/release 1000회
  const pool = new BufferPool();

  runner.add(
    'BufferPool acquire/release x1000',
    'ML/Tensor',
    () => {
      for (let i = 0; i < 1000; i++) {
        const buf = pool.acquire(256);
        pool.release(buf);
      }
    },
    100
  );
}

// ============================================================
// 스위트 빌더: Collections (Phase 9)
// ============================================================

export function addCollectionsBenches(runner: BenchmarkRunner): void {
  // HashMap set/get 10000회
  runner.add(
    'HashMap 10000 set/get',
    'Collections',
    () => {
      const map = new FL8HashMap<string, number>();
      for (let i = 0; i < 10000; i++) {
        map.set(`key_${i}`, i);
      }
      for (let i = 0; i < 10000; i++) {
        map.get(`key_${i}`);
      }
    },
    50
  );

  // PriorityQueue 1000 enqueue/dequeue
  runner.add(
    'PriorityQueue 1000 enq/deq',
    'Collections',
    () => {
      const pq = new FL8PriorityQueue<number>();
      for (let i = 0; i < 1000; i++) {
        pq.enqueue(i, Math.random());
      }
      while (!pq.isEmpty()) {
        pq.dequeue();
      }
    },
    100
  );

  // Queue FIFO 10000회
  runner.add(
    'Queue FIFO 10000',
    'Collections',
    () => {
      const q = new FL8Queue<number>();
      for (let i = 0; i < 10000; i++) {
        q.enqueue(i);
      }
      while (!q.isEmpty()) {
        q.dequeue();
      }
    },
    50
  );
}

// ============================================================
// 스위트 빌더: Type Checker (Phase 8)
// ============================================================

export function addTypeCheckerBenches(runner: BenchmarkRunner): void {
  runner.add(
    '타입 체크 simple x100',
    'TypeChecker',
    () => {
      const tokens = tokenize(TYPE_CHECK_SRC);
      const { program } = new Parser(tokens).parse();
