  );
}

// ============================================================
// buildFullSuite — 전체 스위트 조립
// ============================================================

export function buildFullSuite(): BenchmarkRunner {
  const runner = new BenchmarkRunner('FreeLang v8 ML — Phase 14 Benchmark Suite');

  addLexerParserBenches(runner);
  addInterpreterBenches(runner);
  addMLBenches(runner);
  addCollectionsBenches(runner);
  addTypeCheckerBenches(runner);

  return runner;
}

// FreeLang v8 ML — Phase 14 벤치마크 스위트 테스트

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { bench, BenchmarkRunner, BenchResult, BenchSuite } from '../src/bench/benchmark';
import {
  buildFullSuite,
