} from '../src/bench/suites';

// ============================================================
// 테스트 프레임워크
// ============================================================

let passed = 0;
let failed = 0;

function test(name: string, fn: () => void) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (e: any) {
    console.log(`  ✗ ${name}: ${e.message}`);
    failed++;
  }
}

function assert(cond: boolean, msg: string) {
  if (!cond) throw new Error(msg);
}

function assertGt(a: number, b: number, label: string) {
  if (!(a > b)) throw new Error(`${label}: ${a} > ${b} 기대`);
}

function assertIsNumber(v: unknown, label: string) {
  if (typeof v !== 'number' || isNaN(v) || !isFinite(v)) {
    throw new Error(`${label}: 유효한 숫자 기대, 실제=${v}`);
  }
}

// ============================================================
// 1. bench() 함수 기본 동작
// ============================================================

console.log('\n── bench() 기본 동작 ──');

test('bench: 결과 필드 존재', () => {
  const r = bench('noop', 'Test', () => { let _x = 1 + 1; }, 10);
  assert(typeof r.name === 'string' && r.name === 'noop', 'name 불일치');
  assert(typeof r.category === 'string' && r.category === 'Test', 'category 불일치');
  assert(typeof r.runs === 'number', 'runs 타입 오류');
  assert(typeof r.avgMs === 'number', 'avgMs 타입 오류');
  assert(typeof r.minMs === 'number', 'minMs 타입 오류');
  assert(typeof r.maxMs === 'number', 'maxMs 타입 오류');
  assert(typeof r.opsPerSec === 'number', 'opsPerSec 타입 오류');
});

test('bench: avgMs > 0', () => {
  // CPU 연산이 있는 함수로 측정
  const r = bench('math', 'Test', () => {
    let s = 0;
    for (let i = 0; i < 1000; i++) s += Math.sqrt(i);
    return s;
  }, 20);
  assertGt(r.avgMs, 0, 'avgMs');
});

test('bench: opsPerSec > 0', () => {
  const r = bench('simple', 'Test', () => { let _x = Math.sqrt(2); }, 20);
  assertGt(r.opsPerSec, 0, 'opsPerSec');
});

test('bench: runs 수 일치', () => {
  const r = bench('runs_check', 'Test', () => {}, 42);
  assert(r.runs === 42, `runs=${r.runs}, 기대=42`);
});

test('bench: minMs <= avgMs <= maxMs', () => {
  const r = bench('order', 'Test', () => {
    let s = 0;
    for (let i = 0; i < 500; i++) s += i;
  }, 30);
  assert(r.minMs <= r.avgMs + 0.001, `minMs(${r.minMs}) > avgMs(${r.avgMs})`);
  assert(r.avgMs <= r.maxMs + 0.001, `avgMs(${r.avgMs}) > maxMs(${r.maxMs})`);
});

// ============================================================
// 2. BenchmarkRunner 기본 동작
// ============================================================

console.log('\n── BenchmarkRunner 기본 동작 ──');

test('runner: add + run 반환 BenchSuite', () => {
  const runner = new BenchmarkRunner('Test Suite');
  runner.add('t1', 'Cat', () => { let _x = 1 + 1; }, 10);
  runner.add('t2', 'Cat', () => { let _x = 2 * 3; }, 10);

  const suite = runner.run();
  assert(suite.name === 'Test Suite', 'suite.name 불일치');
  assert(Array.isArray(suite.results), 'results 배열 아님');
  assert(suite.results.length === 2, `results.length=${suite.results.length}`);
  assertIsNumber(suite.totalMs, 'totalMs');
  assert(typeof suite.timestamp === 'string', 'timestamp 타입');
});

test('runner: totalMs > 0', () => {
  const runner = new BenchmarkRunner();
  runner.add('t', 'X', () => {
    let s = 0;
    for (let i = 0; i < 1000; i++) s += i;
  }, 20);
